let shotMode='shots',clipIndex=0;
const shotImportDialog=document.createElement('dialog');shotImportDialog.innerHTML='<div class="modal-head"><h2>导入分镜 JSON</h2><button id="shotImportClose">✕</button></div><p>保留角色与场景。新版主子分镜将旧版脚本和视频完整归档；同结构导入保留匹配的生成记录。</p><label class="drop">选择分镜 JSON 文件<input id="shotImportFile" type="file" accept=".json,.txt,application/json" hidden></label><textarea id="shotImportText" rows="9" placeholder="粘贴 shot_script JSON"></textarea><label style="display:flex;gap:8px;align-items:center"><input id="shotImportCurrentProject" type="checkbox" checked style="width:18px;flex:none">按当前项目编号导入，保留当前角色和场景</label><p id="shotImportProjectInfo" class="subtle"></p><p id="shotImportStatus" role="status"></p><button id="shotImportApply" class="primary">导入分镜</button>';document.body.append(shotImportDialog);
function prepareShotImport(raw){const source=raw?.project_id||'',current=data.project_id||'';document.querySelector('#shotImportProjectInfo').textContent='当前项目：'+data.title+' · '+current+'；文件编号：'+(source||'未填写');if(document.querySelector('#shotImportCurrentProject').checked&&current){return{...raw,...(source&&source!==current?{source_project_id:source}:{}),project_id:current};}return raw;}
document.querySelector('#shotImportClose').onclick=()=>shotImportDialog.close();
document.querySelector('#shotImportFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024)throw Error('文件请小于8MB');document.querySelector('#shotImportText').value=await file.text();const result=ShotSchema.merge(data,prepareShotImport(JSON.parse(document.querySelector('#shotImportText').value)));document.querySelector('#shotImportStatus').textContent=result.sub_count?'识别 '+result.count+' 个主分镜 · '+result.sub_count+' 个子分镜 · '+result.duration+' 秒':'识别 '+result.count+' 个镜头 · '+result.duration+' 秒 · '+(result.project.shotScript.generation_clips?.length||0)+' 个片段';e.target.value='';}catch(error){document.querySelector('#shotImportStatus').textContent=error.message}};
function importShotScript(raw){const result=ShotSchema.merge(data,raw);data=result.project;si=0;tab=2;save();render();toast('已导入 '+result.count+' 个镜头，片段时间轴已整理');}
document.querySelector('#shotImportApply').onclick=()=>{try{importShotScript(prepareShotImport(JSON.parse(document.querySelector('#shotImportText').value)));shotImportDialog.close()}catch(error){document.querySelector('#shotImportStatus').textContent=error.message}};
const importBeforeShotScript=importProject;importProject=function(raw){if(raw?.schema_type==='shot_script'){importShotScript(raw);document.querySelector('#importDialog').close();return}importBeforeShotScript(raw)};
function shotReferenceChoices(binding){if(binding.type==='scene'){const s=data.scenes?.find(s=>(s.id||s.scene_id)===binding.ref_id),counts={};const items=(s?.sceneVersions||[]).filter(v=>v.image_url&&(!v.status||v.status==='completed')).map(v=>{const key=v.view_key||'master',n=counts[key]=(counts[key]||0)+1,anchor=(s?.camera_anchors||[]).find(a=>a.id===key),label=key==='master'?'主图':key+(anchor?.description?' · '+anchor.description:'');return{id:v.id,url:v.image_url,label:label+' V'+n+(v.upscaled_from?' · 高清':'')+(v.width&&v.height?' · '+v.width+' × '+v.height:'')};});return{name:s?.name||binding.ref_id,items,active:s?.activeVersions?.master||items.find(i=>i.id===s?.jobs?.master?.id)?.id};}if(binding.type==='character'){const c=data.characters.find(c=>(c.id||c.character_id)===binding.ref_id);const sheets=(c?.contactSheets||[]).map((v,i)=>({id:v.id,url:v.image_url||'/api/contact-sheet/'+v.id+'/image',label:'人物多视图合照 V'+(i+1)}));const fronts=(c?.versions||[]).filter(v=>v.image_url).map((v,i)=>({id:v.job_id,url:v.image_url,label:'正面 V'+(i+1)}));return{name:c?.name||binding.ref_id,items:[...sheets,...fronts,...(c?.singleViews||[]).map((v,i)=>({id:v.id,url:v.image_url,label:(v.label||'裁剪单视图')+' V'+(i+1)+(v.upscaled_from?' · 高清':'')+(v.width&&v.height?' · '+v.width+' × '+v.height:'')})),...Object.entries(activeMulti(c)?.jobs||{}).filter(([angle,j])=>angle!=='right'&&j.status==='completed'&&j.image_url).map(([angle,j])=>({id:j.id,url:j.image_url,label:({portrait:'半身大头像',left:'单侧面',back:'背面'})[angle]||angle}))],active:(Number.isInteger(c?.contactSheetActive)&&sheets[c.contactSheetActive]?sheets[c.contactSheetActive]:sheets.at(-1))?.id||c?.versions?.[c.active]?.job_id};}return{name:binding.ref_id,items:[]};}
function shotResolvedReferences(target){return ShotSchema.bindings(target).map(binding=>{const choices=shotReferenceChoices(binding);const pinned=target.pictureSelections?.[binding.picture];const item=pinned?choices.items.find(v=>v.id===pinned):choices.items.find(v=>v.id===choices.active)||choices.items.at(-1);return{...binding,name:choices.name,item,choices};});}
function referenceCards(target){return '<div class="shot-reference-grid">'+shotResolvedReferences(target).map((r,i)=>`<div class="shot-reference-card"><b>${esc(r.picture)} · ${esc(r.name)}</b>${r.item?`<a href="${esc(r.item.url)}" target="_blank" rel="noopener"><img src="${esc(r.item.url)}" alt="${esc(r.picture+' '+r.name)}"></a>`:'<p class="subtle">缺少可用参考图</p>'}<select data-shot-ref="${i}" aria-label="${esc(r.picture+' 参考版本')}"><option value="">跟随当前版本${r.item?' · '+esc(r.item.label):''}</option>${r.choices.items.map(v=>`<option value="${esc(v.id)}" ${target.pictureSelections?.[r.picture]===v.id?'selected':''}>固定 ${esc(v.label)}</option>`).join('')}</select><small>${r.item?esc(r.item.id):'请先在角色或场景页生成'}</small></div>`).join('')+'</div>';}
function exportShotScript(){const blob=new Blob([JSON.stringify(ShotSchema.pack(data),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(data.title||'项目')+'-shots.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadShotBindings(target){const refs=shotResolvedReferences(target);if(refs.some(r=>!r.item)){toast('请先补齐缺失参考图');return}const payload={id:target.shot_id||target.clip_id,picture_inputs:refs.map(r=>({picture:r.picture,type:r.type,ref_id:r.ref_id,name:r.name,image_url:new URL(r.item.url,location.origin).href,version_id:r.item.id})),image_prompt:target.prompt||target.image_generation?.prompt,video_prompt:target.clip_id?(target.custom_video_prompt||target.video_prompt):target.video_generation?.prompt};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=payload.id+'-参考图绑定.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function shotJsonField(label,value,id){return field(label,id,JSON.stringify(value||[],null,2),4);}
shots=function(){data.shots??=[];if(si>=data.shots.length)si=0;const clips=data.shotScript?.generation_clips||[];if(clipIndex>=clips.length)clipIndex=0;const check=ShotSchema.reconcile(data),s=shotMode==='clips'?clips[clipIndex]:data.shots[si];const header=`<div class="section-head"><div><h3>把故事，拆成每一个镜头</h3><p>${data.shots.length} 个镜头 · ${clips.length} 个片段 · ${check.duration} 秒 / 目标 ${data.shotScript?.target_duration_seconds||data.target_duration_seconds||120} 秒</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button id="shotImportOpen">↓ 导入分镜 JSON</button><button id="shotExportAll">导出分镜 JSON</button><button id="shotListMode">逐镜脚本</button><button id="shotClipMode">片段与时间轴</button></div></div>`;const warnings=check.warnings.length?`<p class="notice">${esc(check.warnings.join('；'))}</p>`:'';if(!s){document.querySelector('#panel').innerHTML=header+'<div class="card empty-stage">导入分镜 JSON，开始编辑镜头、对白与参考图片。</div>';bindShotHeader();return;}
const clip=shotMode==='clips';const list=clip?clips:data.shots;const index=clip?clipIndex:si;
document.querySelector('#panel').innerHTML=header+warnings+`<div class="editor shot-script-editor"><div class="card shot-list"><div class="mini-label">${clip?'生成片段':'镜头列表'} / ${list.length}</div>${list.map((item,i)=>`<button data-script-item="${i}" class="${i===index?'primary':''}"><b>${esc(item.shot_id||item.clip_id)}</b>　${item.start_time}–${item.end_time}s<small style="display:block;margin-top:6px">${esc(clip?item.shot_ids.join(' + '):item.description)}</small></button>`).join('')}</div><div class="card"><div class="preview-head"><b>${esc(s.shot_id||s.clip_id)} · ${esc(data.scenes?.find(x=>x.id===s.scene_id)?.name||s.scene_name||s.scene_id)}</b><span class="subtle">${s.duration} 秒</span></div>${clip?`<div class="shot-timeline">${s.timeline.map(t=>`<div class="card"><b>${t.start}–${t.end} 秒 · ${esc(t.shot_id)}</b><p>${esc(t.camera)}</p><p>${esc(t.action)}</p>${(t.dialogue||[]).map(d=>`<p class="subtle">${esc(data.characters.find(c=>c.id===d.speaker_id)?.name||'画外声音')}：${esc(d.text)}</p>`).join('')}</div>`).join('')}</div>`:`<h3>${esc(s.description)}</h3><p class="subtle">镜头：${esc(s.camera)} · ${esc(s.generation_clip_id||'未分组')}</p><p>${(s.dialogue||[]).map(d=>esc((data.characters.find(c=>c.id===d.speaker_id)?.name||'画外声音')+'：'+d.text)).join('<br>')||'无对白'}</p>`}<div class="divider"></div><b>实际参考图片 · 按 Picture 编号顺序</b><p class="subtle">场景在前，角色按本镜头或片段的绑定顺序排列；编号不互换。</p>${referenceCards(s)}<button id="downloadShotBindings" class="wide">导出此${clip?'片段':'镜头'}参考图绑定</button><p class="subtle">此页编辑脚本与参考绑定；首帧和视频生成尚未接入，不会创建演示图片。</p></div><div class="card"><div class="right-title">${clip?'片段生成设置':'镜头设定'}</div>${clip?`${field('视频提示词（片段内相对时间）','clipPrompt',s.custom_video_prompt||s.video_prompt,14)}<button id="resetClipPrompt">根据镜头重建提示词</button><p class="subtle">同场景相邻镜头组合，每段最多 ${data.shotScript.rules?.max_generation_clip_seconds||10} 秒。多镜头切换不保证精确，可逐镜生成。</p>`:`${field('画面与动作','scriptAction',s.description,4)}${field('景别与运镜','scriptCamera',s.camera)}${field('时长（秒）','scriptDuration',s.duration)}${shotJsonField('对白（speaker_id / text）',s.dialogue,'scriptDialogue')}${shotJsonField('音效列表',s.sound_effects,'scriptSound')}${field('首帧图像提示词','scriptImagePrompt',s.prompt,8)}${field('负面提示词','scriptNegative',s.image_generation?.negative_prompt||'',3)}${field('视频提示词','scriptVideoPrompt',s.video_generation?.prompt||'',8)}<p id="scriptEditStatus" class="subtle" role="status">修改后自动保存到本机</p>`}</div></div>`;
bindShotHeader();document.querySelectorAll('[data-script-item]').forEach(b=>b.onclick=()=>{if(clip)clipIndex=Number(b.dataset.scriptItem);else si=Number(b.dataset.scriptItem);render()});document.querySelectorAll('[data-shot-ref]').forEach(select=>select.onchange=()=>{s.pictureSelections??={};const binding=ShotSchema.bindings(s)[Number(select.dataset.shotRef)];s.pictureSelections[binding.picture]=select.value||undefined;save();render()});document.querySelector('#downloadShotBindings').onclick=()=>downloadShotBindings(s);
if(clip){document.querySelector('#clipPrompt').oninput=e=>{s.custom_video_prompt=e.target.value;save()};document.querySelector('#resetClipPrompt').onclick=()=>{delete s.custom_video_prompt;save();render()};return;}
function changed(){ShotSchema.reconcile(data);save();}for(const [id,property] of [['scriptAction','description'],['scriptCamera','camera'],['scriptImagePrompt','prompt']])document.querySelector('#'+id).oninput=e=>{s[property]=e.target.value;changed()};const duration=document.querySelector('#scriptDuration');duration.type='number';duration.min='0.1';duration.step='0.1';duration.onchange=()=>{const value=Number(duration.value);if(!Number.isFinite(value)||value<=0){toast('时长必须大于0');return}s.duration=value;changed();render()};for(const [id,property] of [['scriptDialogue','dialogue'],['scriptSound','sound_effects']])document.querySelector('#'+id).oninput=e=>{try{const value=JSON.parse(e.target.value);if(!Array.isArray(value)||value.some(v=>property==='dialogue'?(!v||typeof v.text!=='string'||typeof v.speaker_id!=='string'):typeof v!=='string'))throw Error();s[property]=value;changed();document.querySelector('#scriptEditStatus').textContent='已保存';}catch{document.querySelector('#scriptEditStatus').textContent='JSON 格式尚未完成，保留上次有效内容。'}};document.querySelector('#scriptNegative').oninput=e=>{s.image_generation.negative_prompt=e.target.value;changed()};document.querySelector('#scriptVideoPrompt').oninput=e=>{s.video_generation??={};s.video_generation.prompt=e.target.value;changed()};
};
function bindShotHeader(){document.querySelector('#shotImportOpen').onclick=()=>shotImportDialog.showModal();document.querySelector('#shotExportAll').onclick=exportShotScript;document.querySelector('#shotListMode').onclick=()=>{shotMode='shots';render()};document.querySelector('#shotClipMode').onclick=()=>{shotMode='clips';render()};}
const shotModuleExport=document.createElement('button');shotModuleExport.textContent='05 分镜 · 镜头与生成片段';shotModuleExport.onclick=exportShotScript;document.querySelector('#moduleExports').append(shotModuleExport);render();
